import { usePanier } from "../hooks/usePanier";
import LignePanier from "../components/panier/LignePanier";
import RecapitulatifPanier from "../components/panier/RecapitulatifPanier";

export default function Panier() {
  const { panier } = usePanier();

  return (
    <div style={{ padding: "30px", maxWidth: "900px", margin: "0 auto" }}>
      <h2 style={{ marginBottom: "20px" }}>Mon Panier</h2>
      {panier.length === 0 ? (
        <p>Votre panier est vide.</p>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: "20px" }}>
          <div>{panier.map((a) => <LignePanier key={a.id} article={a} />)}</div>
          <RecapitulatifPanier />
        </div>
      )}
    </div>
  );
}
